class Solution:
    def smallestTrimmedNumbers(self, nums: List[str], queries: List[List[int]]) -> List[int]:
        res = []
        for k, t in queries:
            order = sorted(range(len(nums)), key=lambda i: (nums[i][-t:], i))
            res.append(order[k - 1])
        return res

