class Solution:
    def smallestTrimmedNumbers(self, nums: List[str], queries: List[List[int]]) -> List[int]:
        n, L = len(nums), len(nums[0])
        cur = list(range(n))
        saved = {}
        for pos in range(L - 1, -1, -1):
            buckets = [[] for _ in range(10)]
            for i in cur:
                buckets[int(nums[i][pos])].append(i)
            cur = [i for b in buckets for i in b]
            saved[L - pos] = cur[:]
        return [saved[t][k - 1] for k, t in queries]

