class Solution {
public:
    vector<int> smallestTrimmedNumbers(vector<string>& nums, vector<vector<int>>& queries) {
        int n = nums.size(), L = nums[0].size();
        vector<int> cur(n);
        iota(cur.begin(), cur.end(), 0);
        unordered_map<int, vector<int>> saved;
        for (int pos = L - 1; pos >= 0; --pos) {
            vector<vector<int>> buckets(10);
            for (int i : cur) buckets[nums[i][pos] - '0'].push_back(i);
            cur.clear();
            for (auto& b : buckets) for (int i : b) cur.push_back(i);
            saved[L - pos] = cur;
        }
        vector<int> res;
        for (auto& q : queries) res.push_back(saved[q[1]][q[0] - 1]);
        return res;
    }
};

