class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length, L = nums[0].length();
        List<Integer> cur = new ArrayList<>();
        for (int i = 0; i < n; i++) cur.add(i);
        Map<Integer, List<Integer>> saved = new HashMap<>();
        for (int pos = L - 1; pos >= 0; pos--) {
            List<List<Integer>> buckets = new ArrayList<>();
            for (int d = 0; d < 10; d++) buckets.add(new ArrayList<>());
            for (int i : cur) buckets[nums[i].charAt(pos) - '0'].add(i);
            cur = new ArrayList<>();
            for (List<Integer> b : buckets) cur.addAll(b);
            saved.put(L - pos, new ArrayList<>(cur));
        }
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++)
            res[qi] = saved.get(queries[qi][1]).get(queries[qi][0] - 1);
        return res;
    }
}

