var smallestTrimmedNumbers = function(nums, queries) {
    const n = nums.length, L = nums[0].length;
    let cur = nums.map((_, i) => i);
    const saved = {};
    for (let pos = L - 1; pos >= 0; pos--) {
        const buckets = Array.from({length: 10}, () => []);
        for (const i of cur) buckets[+nums[i][pos]].push(i);
        cur = buckets.flat();
        saved[L - pos] = [...cur];
    }
    return queries.map(([k, t]) => saved[t][k - 1]);
};
